<?php require_once __DIR__.'/comman/auth.php'; $pageTitle="Promo Codes"; require __DIR__.'/comman/header.php'; require __DIR__.'/comman/sidebar.php'; ?><div class="content-wrapper"><section class="content-header"><div class="container-fluid"><div class="row mb-2"><div class="col-sm-8"><h1><?=h($pageTitle)?></h1></div></div><?php if($flash):?><div class="alert alert-<?=h($flash[0])?>"><?=h($flash[1])?></div><?php endif;?></div></section><section class="content"><div class="container-fluid"><?php $promos=admin_data('promo_codes.json',[]);$games=read_json(SITE_ROOT.'/data/games.json',[]);if(isset($_GET['delete'])){if(!hash_equals(csrf(),$_GET['csrf']??''))die('Invalid request');$id=(string)$_GET['delete'];$promos=array_values(array_filter($promos,fn($p)=>($p['id']??'')!==$id));admin_save('promo_codes.json',$promos);flash('success','Promo code deleted.');redirect_admin('promo_codes.php');}if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$gs=slugify(post_str('gameSlug'));$gn='';foreach($games as $g){if(($g['slug']??'')===$gs){$gn=$g['name'];break;}}$promos[]=['id'=>uniqid('promo_'),'gameSlug'=>$gs,'gameName'=>$gn,'code'=>post_str('code'),'reward'=>post_str('reward'),'minDeposit'=>post_str('minDeposit'),'expiry'=>post_str('expiry'),'terms'=>post_str('terms'),'status'=>bool_post('status'),'createdAt'=>date('c')];admin_save('promo_codes.json',$promos);flash('success','Promo code saved.');redirect_admin('promo_codes.php');}?><div class="row"><div class="col-md-5"><div class="card"><div class="card-header"><h3 class="card-title">Add Daily Promo Code</h3></div><div class="card-body"><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><div class="form-group"><label>Game</label><select class="form-control" name="gameSlug" required><option value="">Select Game</option><?php foreach($games as $g):?><option value="<?=h($g['slug'])?>"><?=h($g['name'])?></option><?php endforeach;?></select></div><div class="form-group"><label>Promo Code</label><input class="form-control" name="code" required></div><div class="form-group"><label>Reward / Offer</label><input class="form-control" name="reward"></div><div class="form-group"><label>Minimum Deposit</label><input class="form-control" name="minDeposit"></div><div class="form-group"><label>Expiry</label><input class="form-control" name="expiry"></div><div class="form-group"><label>Terms / Eligibility</label><textarea class="form-control" name="terms"></textarea></div><div class="custom-control custom-checkbox mb-3"><input class="custom-control-input" id="ps" type="checkbox" name="status" checked><label class="custom-control-label" for="ps">Active</label></div><button class="btn btn-pink btn-block">Save Promo Code</button></form></div></div></div><div class="col-md-7"><div class="card"><div class="card-header"><h3 class="card-title">Promo Code History</h3></div><div class="card-body table-responsive"><table class="table"><thead><tr><th>Game</th><th>Code</th><th>Offer</th><th>Expiry</th><th></th></tr></thead><tbody><?php foreach(array_reverse($promos) as $p):?><tr><td><?=h($p['gameName'])?></td><td><code><?=h($p['code'])?></code></td><td><?=h($p['reward'])?></td><td><?=h($p['expiry'])?></td><td><a class="btn btn-sm btn-outline-danger" href="promo_codes.php?delete=<?=urlencode($p['id'])?>&csrf=<?=h(csrf())?>" onclick="return confirm('Delete?')">Delete</a></td></tr><?php endforeach;?></tbody></table></div></div></div></div></div></section></div><?php require __DIR__.'/comman/footer.php'; ?>